PREFIX ns: <http://rdf.freebase.com/ns/>   
SELECT DISTINCT ?relation   
WHERE {   
ns:%s ?relation ?x .   
FILTER (?x != ns:%s)   
}

PREFIX ns: <http://rdf.freebase.com/ns/>   
SELECT DISTINCT ?relation   
WHERE {   
?x ?relation ns:%s .   
FILTER (?x != ns:%s)   
}

PREFIX ns: <http://rdf.freebase.com/ns/>   
SELECT ?tailEntity   
WHERE {   
ns:%s ns:%s ?tailEntity .   
}

PREFIX ns: <http://rdf.freebase.com/ns/>   
SELECT ?tailEntity   
WHERE {   
?tailEntity ns:%s ns:%s .   
}
